import csv
rows=[]
C={'BGD':BGD,'CHN':CHN,'IND':IND,'NGA':NGA,'PAK':PAK,'PHL':PHL,'ZAF':ZAF}
with open('unwpp_youth_share.csv','w',newline='') as f:
    w=csv.writer(f); w.writerow(['year']+[f'{k}_1524' for k in C]+[f'{k}_1564' for k in C])
    P={k:[list(map(float,x.split())) for x in v.split('|')] for k,v in C.items()}
    for k,v in P.items(): assert len(v)==44,(k,len(v))
    for i,y in enumerate(range(1976,2020)):
        a=[P[k][i][2]/sum(P[k][i]) for k in C]; b=[(P[k][i][1]+P[k][i][2])/sum(P[k][i]) for k in C]
        w.writerow([y]+[round(x,5) for x in a+b])
print('ok')
